    /** Event will be fired when Swiper reach its beginning (initial position)
     *  @ignore 
     */
    @Output() reachBeginning = new EventEmitter<Pick<SwiperInterfaceOptions, 'swiper'>>();

    /** Event will be fired when Swiper reach last slide
     *  @ignore 
