            border-radius: 4px;
            cursor: pointer;
            font-weight: 500;
            transition: background-color 0.2s, transform 0.1s;
          }
          .btn-ng:hover {
            background-color: #1e88e5;
          }
          .btn-ng:active {
            transform: scale(0.98);
          }
          .btn-highlight {
            background-color: #ff9800 !important;
            box-shadow: 0 0 10px rgba(255, 152, 0, 0.6);
